// Compiled-in M4 eye sets (Phase 1). Each is generated by
// tools/m4eye_convert.py --header from an M4_Eyes eye folder.
#pragma once
#include <stdint.h>

namespace m4eye {

struct EyeSet {
  const char* name;
  const char* json;  // converted config.eye (160 px radii)
  const uint16_t* iris;  // big-endian RGB565, nullptr = flat irisColor
  int irisW, irisH;
  const uint16_t* sclera;  // nullptr = flat scleraColor
  int scleraW, scleraH;
  int numLids;
  const char* const* lidNames;
  const uint8_t (*lids)[4][160];  // upperOpen, upperClosed, lowerOpen, lowerClosed
};

extern const EyeSet kEyeSets[];
extern const int kNumEyeSets;

}  // namespace m4eye
